jQuery.tablesorter.addParser({ 
	id: "currencyWithComma", 
	is: function(s) { 
		return false; 
	}, 
	format: function(s) { 
		return s.replace(/\D/g, '');
	}, 
	type: "numeric"
}); 

jQuery.tablesorter.addParser({ 
	id: "entries", 
	is: function(s) { 
		return false; 
	}, 
	format: function(s) { 
		return s.split("/")[1].replace('k', '00').replace('.','')
	}, 
	type: "numeric"
}); 


jQuery.tablesorter.addParser({
    id: "numericalInput",
    is: function(s){
        return false;
    },
    format: function(s, table, cell) {
        const value = cell.querySelector('input')?.value || cell.textContent
        return parseFloat(value)
    },
    type: "numeric"
});

