    // Coach is a large bundle that most visitors never open, and requesting it at
    // parse time made it compete with the bundles that render the page. It is now
    // prefetched once the page is idle and only executed when someone asks for it.
    //
    // Two things have to stay true for that to be safe:
    //
    // 1. The panel listens for `toggle-coach`, and that listener only exists after
    //    the bundle mounts (CoachAiApp.vue onMounted -> toggleCoach). Eight places
    //    dispatch the event - nav, icon-nav, CoachAiTrigger, NavResultsMobile,
    //    rankings, DraftPrepModule, TradePersuade, McuCoachModule - and all of them
    //    are interactive long before that. So we listen ourselves, pull the bundle
    //    forward, and replay the event once the app is up. The listener comes down
    //    only once the app has actually taken over - not when the request starts,
    //    and not merely when the script loads: anything in between still has to
    //    land somewhere.
    //
    // 2. Consumers decide whether to show their Coach controls at all by checking
    //    `window.COACH.fillPrompt` (vue/rankings/App.vue showCoachPromptsFlag,
    //    McuCoachModule.vue hasGlobalFillPrompt). If we defer the bundle without
    //    publishing that, we hide the very controls that would request it. So the
    //    capability is declared here immediately and the call is replayed later.
    (function () {
        var src = '//cdn.fantasypros.com/assets/js/min/pages/coach/bundle-19cf11d5c7fa554b3322.js';

        var loading = false;
        var ready = false;
        var pendingToggle = null;
        var pendingPrompt = null;

        var shouldOpen = false;
        try {
            shouldOpen = sessionStorage.getItem('fp_coach_ai_show') === 'true';
        } catch (e) {}

        function stubFillPrompt(label) {
            pendingPrompt = label;
            loadCoach();
        }

        window.COACH = window.COACH || {};
        if (typeof window.COACH.fillPrompt !== 'function') {
            window.COACH.fillPrompt = stubFillPrompt;
        }

        function onEarlyToggle(event) {
            pendingToggle = (event && event.detail !== undefined) ? event.detail : 'open';
            loadCoach();
        }

        window.addEventListener('toggle-coach', onEarlyToggle);

        function handOver() {
            // Downloading is not the same as taking over. If mount throws - and
            // CoachAiApp.onMounted runs checkIsApp() and getMessageCount() before it
            // registers anything - the bundle is here but window.COACH is still ours
            // and nothing listens for toggle-coach. Latching `ready` on load alone
            // would leave the button dead with no retry, so check for the handover.
            var appTookOver = !!window.COACH
                && typeof window.COACH.fillPrompt === 'function'
                && window.COACH.fillPrompt !== stubFillPrompt;

            if (!appTookOver) {
                loading = false;
                document.documentElement.removeAttribute('data-coach-loading');
                // keep the shim listening; a later click retries, up to the cap
                return;
            }

            // the app owns `toggle-coach` and window.COACH from here
            window.removeEventListener('toggle-coach', onEarlyToggle);
            ready = true;
            loading = false;
            document.documentElement.removeAttribute('data-coach-loading');

            if (shouldOpen && pendingToggle === null) {
                pendingToggle = 'open';
            }

            if (pendingPrompt !== null) {
                if (typeof window.COACH.fillPrompt === 'function') {
                    window.COACH.fillPrompt(pendingPrompt);
                }
                pendingPrompt = null;
            }

            if (pendingToggle !== null) {
                window.dispatchEvent(new CustomEvent('toggle-coach', { detail: pendingToggle }));
                pendingToggle = null;
            }
        }

        var attempts = 0;
        var MAX_ATTEMPTS = 2;

        function loadCoach() {
            if (loading || ready) return;
            // a bundle that keeps failing to take over will not start working on the
            // fifth click; stop re-downloading it
            if (attempts >= MAX_ATTEMPTS) return;

            attempts++;
            loading = true;
            // hook for a pending state on the trigger; styles nothing today
            document.documentElement.setAttribute('data-coach-loading', '');

            var script = document.createElement('script');
            script.src = src;
            script.async = true;
            script.onload = handOver;
            script.onerror = function () {
                // let the next click retry rather than dead-clicking all session
                loading = false;
                document.documentElement.removeAttribute('data-coach-loading');
            };
            document.body.appendChild(script);
        }

        var prefetched = false;
        function prefetch() {
            if (prefetched || loading || ready) return;
            prefetched = true;

            var link = document.createElement('link');
            link.rel = 'prefetch';
            link.as = 'script';
            link.href = src;
            document.head.appendChild(link);
        }

        if (shouldOpen) {
            // an explicit request from the previous page, not a background feature
            loadCoach();
        } else if (document.readyState === 'complete') {
            prefetch();
        } else {
            // `load` alone is not enough: on ad-heavy pages it had still not fired
            // 37s in when this was measured, so the prefetch never happened. By
            // ten seconds the critical work is long done and this is lowest
            // priority anyway, so take whichever comes first.
            window.addEventListener('load', prefetch);
            setTimeout(prefetch, 10000);
        }
    })();
</script>


