<script type="text/javascript">
function closeAllModals() {
    document.querySelectorAll('.modal.in').forEach((modal) => {
        // Dispatch hide.bs.modal event (before hiding)
        modal.dispatchEvent(new CustomEvent('hide.bs.modal'));

        // Remove listeners to prevent stacking
        if (modal._closeHandlers) {
            modal.removeEventListener(modal._closeHandlers.eventType, modal._closeHandlers.handler);
            modal.removeEventListener('keyup', modal._closeHandlers.keyup);
            delete modal._closeHandlers;
        }

        // Hide modal
        modal.classList.remove('in');
        modal.setAttribute('aria-hidden', 'true');
        modal.style.display = 'none';

        // Dispatch hidden.bs.modal event (after hiding)
        modal.dispatchEvent(new CustomEvent('hidden.bs.modal'));
    });

    // Remove backdrops
    document.querySelectorAll('.modal-backdrop').forEach((el) => {
        el.remove();
    });
    document.body.classList.remove('modal-open');
}

function openModal(modalSelector, triggerEvent) {
    if (!modalSelector) return;

    const modal = document.querySelector(modalSelector);
    if (!modal) return;

    // Dispatch show.bs.modal event (before showing)
    modal.dispatchEvent(new CustomEvent('show.bs.modal'));

    // Show modal + backdrop
    modal.classList.add('in');
    modal.setAttribute('aria-hidden', 'false');
    modal.style.display = 'block';
    document.body.classList.add('modal-open');

    const backdrop = document.createElement('div');
    backdrop.className = 'modal-backdrop fade in';
    document.body.appendChild(backdrop);

    // Click-outside and ESC close (avoid stacking with named functions)
    const dialog = modal.querySelector('.modal-dialog');
    const onClickOutside = (evt) => {
        if (dialog && !dialog.contains(evt.target)) {
            closeAllModals();
        }
    };
    const onEsc = (e) => {
        if (e.key === 'Escape') {
            closeAllModals();
        }
    };

    // Store handlers on modal for cleanup (track eventType for correct removal)
    const eventType = (!triggerEvent || triggerEvent.type === 'click') ? 'click' : 'touchstart';
    modal._closeHandlers = { eventType: eventType, handler: onClickOutside, keyup: onEsc };

    modal.addEventListener(eventType, onClickOutside);
    modal.addEventListener('keyup', onEsc);

    // Focus the modal so keyboard events (ESC) work
    if (!modal.getAttribute('tabindex')) {
        modal.setAttribute('tabindex', '-1');
    }
    modal.focus();

    // Dispatch shown.bs.modal event (after showing)
    modal.dispatchEvent(new CustomEvent('shown.bs.modal'));
}

document.addEventListener("DOMContentLoaded", () => {
    // Modal toggle triggers
    const modalToggles = document.querySelectorAll('[data-toggle="modal"]');
    modalToggles.forEach((toggle) => {
        toggle.addEventListener('click', (evt) => {
            evt.preventDefault();
            // Check data-target first, then fall back to href
            const modalTarget = toggle.getAttribute('data-target') || toggle.getAttribute('href');
            if (!modalTarget) return;

            openModal(modalTarget, evt);
        });
    });

    // Modal close buttons
    const modalCloses = document.querySelectorAll('[data-dismiss="modal"]');
    modalCloses.forEach((closeModal) => {
        closeModal.addEventListener("click", () => {
            closeAllModals();
        });
    });

    // Bootstrap tab toggle (vanilla replacement)
    document.addEventListener('click', (e) => {
        const tabLink = e.target.closest('[data-toggle="tab"]');
        if (!tabLink) return;
        e.preventDefault();
        const targetSelector = tabLink.getAttribute('data-target') || tabLink.getAttribute('href');
        if (!targetSelector) return;

        // Deactivate sibling tabs and panes
        const tabList = tabLink.closest('ul');
        if (tabList) {
            tabList.querySelectorAll('li').forEach(li => li.classList.remove('active'));
            const parentLi = tabLink.closest('li');
            if (parentLi) parentLi.classList.add('active');
        }

        // Show target pane, hide siblings
        const targetPane = document.querySelector(targetSelector);
        if (targetPane) {
            const tabContent = targetPane.parentElement;
            if (tabContent) {
                tabContent.querySelectorAll('.tab-pane').forEach(pane => {
                    pane.classList.remove('active', 'in');
                });
            }
            targetPane.classList.add('active', 'in');
        }
    });

    // Bootstrap dropdown toggle (vanilla replacement)
    document.addEventListener('click', (e) => {
        const toggle = e.target.closest('[data-toggle="dropdown"]');
        if (toggle) {
            e.preventDefault();
            const parent = toggle.closest('.btn-group, .dropdown');
            if (parent) {
                const wasOpen = parent.classList.contains('open');
                // Close all open dropdowns first
                document.querySelectorAll('.btn-group.open, .dropdown.open').forEach(el => el.classList.remove('open'));
                if (!wasOpen) parent.classList.add('open');
            }
            return;
        }
        // Close dropdown on menu item click (matches BS3 behavior)
        const menuItem = e.target.closest('.dropdown-menu a, .dropdown-menu button');
        if (menuItem) {
            const openParent = menuItem.closest('.btn-group.open, .dropdown.open');
            if (openParent) openParent.classList.remove('open');
            return;
        }
        // Close dropdowns when clicking outside
        if (!e.target.closest('.btn-group.open, .dropdown.open')) {
            document.querySelectorAll('.btn-group.open, .dropdown.open').forEach(el => el.classList.remove('open'));
        }
    });
});

// jQuery bridge for backward compatibility
if (window.jQuery) {
    jQuery.fn.modal = function(action) {
        return this.each(function() {
            // Build a selector: prefer #id, fall back to generating a temporary id
            let selector;
            if (this.id) {
                selector = '#' + this.id;
            } else {
                const tempId = 'fp-modal-' + Math.random().toString(36).slice(2, 9);
                this.id = tempId;
                selector = '#' + tempId;
            }

            if (action === 'show') {
                openModal(selector);
            } else if (action === 'hide') {
                closeAllModals();
            } else if (action === 'toggle') {
                if (this.classList.contains('in')) {
                    closeAllModals();
                } else {
                    openModal(selector);
                }
            } else {
                openModal(selector);
            }
        });
    };
}
</script>






