function stickyScrollHeader() {
    if (window.innerWidth >= 500) return;

    // :visible has no vanilla equivalent — filter to elements with dimensions
    document.querySelectorAll('.mobile-table.mobile-scroll').forEach((el) => {
        if (el.offsetParent === null) return; // hidden

        const rows = el.querySelectorAll('table thead tr');
        if (!rows.length) return;
        const newTr = rows[rows.length - 1].cloneNode(true);
        newTr.classList.add('sticky-table-header');

        const bodyRows = el.querySelectorAll('table tbody tr');
        if (!bodyRows.length) return;
        const lastTr = bodyRows[bodyRows.length - 1];
        const lastTds = lastTr.querySelectorAll('td');
        const newThs = newTr.querySelectorAll('th');
        for (let i = 0; i < lastTds.length; i++) {
            if (newThs[i]) {
                newThs[i].style.width = (lastTds[i].offsetWidth + 1) + 'px';
            }
        }

        const thead = el.querySelector('table thead');
        if (thead) thead.appendChild(newTr);

        const headerHeight = newTr.offsetHeight;

        const leftCover = document.createElement('div');
        leftCover.className = 'left-head-cover';
        leftCover.style.minHeight = headerHeight + 'px';
        el.appendChild(leftCover);

        const rightCover = document.createElement('div');
        rightCover.className = 'right-head-cover';
        rightCover.style.minHeight = headerHeight + 'px';
        el.appendChild(rightCover);
    });

    function checkTableScroll() {
        const tbl = document.querySelector('.mobile-table.mobile-scroll');
        if (!tbl || tbl.offsetParent === null) return;

        const rect = tbl.getBoundingClientRect();
        const scrollTop = window.scrollY;
        const offsetTop = rect.top + scrollTop;
        if (scrollTop > offsetTop && scrollTop < offsetTop + tbl.offsetHeight) {
            tbl.classList.add('mobile-sticky-header');
        } else {
            tbl.classList.remove('mobile-sticky-header');
        }

        const stickyRow = document.querySelector('.mobile-sticky-header tr.sticky-table-header');
        if (stickyRow) {
            const scrollLeft = tbl.scrollLeft;
            stickyRow.style.left = scrollLeft > 0 ? '-' + (scrollLeft - 10) + 'px' : '10px';
        }
    }

    const scrollTable = document.querySelector('.mobile-table.mobile-scroll');
    if (scrollTable) {
        scrollTable.addEventListener('scroll', checkTableScroll);
    }
    window.addEventListener('scroll', checkTableScroll);
}

function generateTableCaption(container, text) {
    var tableContainer = container || document.getElementById('main-container') || document.getElementById('sport-landing-page-app');
    if (!tableContainer) return;

    var captionText = text || document.title;
    var tables = tableContainer.getElementsByTagName('table');
    const len = tables.length;

    for (var i = 0; i < len; ++i) {
        var table = tables[i];
        var captions = table.getElementsByTagName('caption');
        if (captions.length === 0) {
            var caption = document.createElement('caption');
            caption.className = 'hidden-aria';
            caption.textContent = captionText;
            table.insertBefore(caption, table.childNodes[0]);
            break;
        }
    }
}

if (window.innerWidth < 500 && document.querySelector('.mobile-table.mobile-scroll')) {
    stickyScrollHeader();
}

