                selector = '#' + this.id;
            } else {
                const tempId = 'fp-modal-' + Math.random().toString(36).slice(2, 9);
                this.id = tempId;
                selector = '#' + tempId;
            }

            if (action === 'show') {
                openModal(selector);
            } else if (action === 'hide') {
                closeAllModals();
            } else if (action === 'toggle') {
                if (this.classList.contains('in')) {
                    closeAllModals();
                } else {
                    openModal(selector);
                }
            } else {
                openModal(selector);
            }
        });
