            const endTimestamp = startTimestamp + duration * 60;

            const badgeContainer = document.createElement('div');
            badgeContainer.classList.add('card-event__badges');
            card.prepend(badgeContainer);

            function updateTimer() {
                const currentTimestamp = Math.floor(Date.now() / 1000);
                const timeDifference = startTimestamp - currentTimestamp;

                if (timeDifference > 0) {
                    const hours = Math.floor(timeDifference / 3600);
                    const minutes = Math.floor((timeDifference % 3600) / 60);
                    const seconds = timeDifference % 60;
                    const timeString = `${hours}h ${minutes}m ${seconds}s`;

                    badgeContainer.innerHTML = `<span class="badge-secondary badge-secondary_soon">SOON in ${timeString}</span>`;
                } else if (currentTimestamp <= endTimestamp) {
                    badgeContainer.innerHTML = `<span class="badge-secondary badge-secondary_live">LIVE</span>`;
                } else {
                    badgeContainer.innerHTML = '';
                }
            }

            updateTimer();

            const timerInterval = setInterval(() => {
                updateTimer();

                if (Math.floor(Date.now() / 1000) > endTimestamp) {
                    clearInterval(timerInterval);
                }
            }, 1000);
        });
    });

